async fn update_firewall(
    ctx: &Context<'_>,
    args: UpdateFirewallArgs,
) -> anyhow::Result<Box<dyn SerializableOutput>> {
    let mut names = ctx
        .names(&[("project", args.project.as_deref()), ("zone", args.zone.as_deref())]);
    names
        .learn(
            &["projects/{project}/zones/{zone}/firewalls/{firewall}"],
            "firewall",
            Some(args.firewall.as_str()),
        )?;
    for keyed in &args.rule {
        let item = &keyed.value;
        names
            .learn(
                &[
                    "projects/{project}/zones/{zone}/networks/{network}",
                    "zones/{zone}/networks/{network}",
                ],
                "rule network",
                Some(item.network.as_str()),
            )?;
    }
    if let Some(json) = &args.rules_json {
        for item in &json.0 {
            names
                .learn(
                    &[
                        "projects/{project}/zones/{zone}/networks/{network}",
                        "zones/{zone}/networks/{network}",
                    ],
                    "rule network",
                    Some(item.network.as_str()),
                )?;
        }
    }
    for value in &args.network {
        names
            .learn(
                &[
                    "projects/{project}/zones/{zone}/networks/{network}",
                    "zones/{zone}/networks/{network}",
                ],
                "network",
                Some(value.as_str()),
            )?;
    }
    names
        .learn(
            &[
                "projects/{project}/zones/{zone}/networks/{network}",
                "zones/{zone}/networks/{network}",
            ],
            "mirror-network",
            args.mirror_network.as_deref(),
        )?;
    let name = names
        .reference(
            &["projects/{project}/zones/{zone}/firewalls/{firewall}"],
            "firewall",
            args.firewall.as_str(),
        )?;
    let mut firewall = ::origincloud_scratch::v1::Firewall {
        name: name.clone(),
        ..::core::default::Default::default()
    };
    let mut paths: Vec<String> = Vec::new();
    if !args.rule.is_empty() || args.rules_json.is_some() {
        let mut value = match args.rules_json {
            Some(json) => {
                notice_replaced("--rules-json", "rules", json.0.len());
                json.0
            }
            None => {
                let items: Vec<_> = args
                    .rule
                    .into_iter()
                    .map(|keyed| keyed.value)
                    .collect();
                notice_replaced("--rule", "rules", items.len());
                items
            }
        };
        for item in &mut value {
            if !item.network.is_empty() {
                item.network = names
                    .reference(
                        &[
                            "projects/{project}/zones/{zone}/networks/{network}",
                            "zones/{zone}/networks/{network}",
                        ],
                        "rule network",
                        item.network.as_str(),
                    )?;
            }
        }
        firewall.rules = value;
        paths.push("rules".to_owned());
    }
    if args.no_ports || !args.port.is_empty() {
        firewall.ports = args.port.clone();
        paths.push("ports".to_owned());
    }
    if args.no_networks || !args.network.is_empty() {
        firewall.networks = args
            .network
            .iter()
            .map(|v| {
                names
                    .reference(
                        &[
                            "projects/{project}/zones/{zone}/networks/{network}",
                            "zones/{zone}/networks/{network}",
                        ],
                        "network",
                        v.as_str(),
                    )
            })
            .collect::<anyhow::Result<Vec<String>>>()?;
        paths.push("networks".to_owned());
    }
    if args.no_aliases || !args.alias.is_empty() {
        unique(&args.alias, "--alias")?;
        firewall.aliases = args.alias.clone();
        paths.push("aliases".to_owned());
    }
    if args.no_logging || args.logging.is_some() || args.logging_json.is_some() {
        let value = match args.logging_json {
            Some(json) => {
                notice_reset(
                    "--logging-json",
                    "logging",
                    &["enabled", "sample_percent"],
                    &json.1,
                );
                Some(json.0)
            }
            None => {
                args.logging
                    .map(|keyed| {
                        notice_reset(
                            "--logging",
                            "logging",
                            &["enabled", "sample_percent"],
                            &keyed.given,
                        );
                        keyed.value
                    })
            }
        };
        firewall.logging = value;
        paths.push("logging".to_owned());
    }
    if args.no_tags || !args.tag.is_empty() {
        firewall.tags = tags(&args.tag);
        paths.push("tags".to_owned());
    }
    if let Some(value) = args.expire_time {
        firewall.expire_time = Some(value);
        paths.push("expire_time".to_owned());
    }
    if args.no_metadata || args.metadata_json.is_some() {
        let value = match args.metadata_json {
            Some(json) => Some(json.0),
            None => None,
        };
        firewall.metadata = value;
        paths.push("metadata".to_owned());
    }
    if args.no_max_connections || args.max_connections.is_some() {
        firewall.max_connections = args.max_connections;
        paths.push("max_connections".to_owned());
    }
    if args.no_strict || args.strict.is_some() {
        firewall.strict = args.strict;
        paths.push("strict".to_owned());
    }
    if args.no_default_protocol || args.default_protocol.is_some() {
        firewall.default_protocol = args
            .default_protocol
            .as_deref()
            .and_then(::origincloud_scratch::v1::rule::Protocol::from_str_name)
            .map(|v| v as i32);
        paths.push("default_protocol".to_owned());
    }
    if args.no_note || args.note.is_some() {
        firewall.note = args.note.clone();
        paths.push("note".to_owned());
    }
    let mirror_log = match args.mirror_log_json {
        Some(json) => {
            notice_reset(
                "--mirror-log-json",
                "mirror_log",
                &["enabled", "sample_percent"],
                &json.1,
            );
            Some(json.0)
        }
        None => {
            args.mirror_log
                .map(|keyed| {
                    notice_reset(
                        "--mirror-log",
                        "mirror_log",
                        &["enabled", "sample_percent"],
                        &keyed.given,
                    );
                    keyed.value
                })
        }
    };
    if let Some(value) = args
        .mirror_network
        .as_deref()
        .map(|v| {
            names
                .reference(
                    &[
                        "projects/{project}/zones/{zone}/networks/{network}",
                        "zones/{zone}/networks/{network}",
                    ],
                    "mirror-network",
                    v,
                )
        })
        .transpose()?
    {
        firewall.mirror = Some(
            ::origincloud_scratch::v1::firewall::Mirror::MirrorNetwork(value),
        );
        paths.push("mirror_network".to_owned());
        paths.push("mirror_address".to_owned());
        paths.push("mirror_log".to_owned());
    } else if let Some(value) = args.mirror_address.clone() {
        firewall.mirror = Some(
            ::origincloud_scratch::v1::firewall::Mirror::MirrorAddress(value),
        );
        paths.push("mirror_network".to_owned());
        paths.push("mirror_address".to_owned());
        paths.push("mirror_log".to_owned());
    } else if let Some(value) = mirror_log {
        firewall.mirror = Some(
            ::origincloud_scratch::v1::firewall::Mirror::MirrorLog(value),
        );
        paths.push("mirror_network".to_owned());
        paths.push("mirror_address".to_owned());
        paths.push("mirror_log".to_owned());
    } else if args.no_mirror {
        firewall.mirror = None;
        paths.push("mirror_network".to_owned());
        paths.push("mirror_address".to_owned());
        paths.push("mirror_log".to_owned());
    }
    let request = ::origincloud_scratch::v1::UpdateFirewallRequest {
        firewall: Some(firewall),
        update_mask: Some(::origincloud_core::protobuf::FieldMask {
            paths,
        }),
    };
    let client = ctx.client()?;
    let response = call_update_firewall(&client, request).await.map_err(api_error)?;
    json(&response, "origincloud.scratch.v1.Firewall")
}
async fn call_update_firewall(
    client: &ReadClient,
    request: ::origincloud_scratch::v1::UpdateFirewallRequest,
) -> ::core::result::Result<
    ::origincloud_scratch::v1::Firewall,
    ::origincloud_core::Error,
> {
    ::origincloud_scratch::v1::FirewallClient::new(client.sdk())
        .update_firewall(request)
        .await
}
